/** Look up a CB-safe color, falling back to the source color if not covered. */
export function getCbColor(
  variableId: string,
  classId: number,
  cbMode: CbMode | null | undefined,
  fallback: string,
): string {
  if (!cbMode) return fallback;
  // Strip temporal suffix (e.g. weather_code_simple_mode_168h → weather_code_simple)
  const baseId = variableId.replace(/_(avg|sum|mode|snapshot)_\d+h$/i, '');
  return CB_CLASS_COLORS[baseId]?.[cbMode]?.[classId] ?? fallback;
}

